// ---------------------------------------------------------------------------
// filmstrip-ledger.ts — the frames, written down so a second reader can draw them
// ---------------------------------------------------------------------------
//
// Why a ledger exists at all
// --------------------------
// `ductusview.ts` already builds the filmstrip. The app calls it directly and
// draws the result into the DOM. The BOOK cannot: the book is generated by
// `@coding-adventures/human-language-data`, which runs as a plain Node CLI —
// and this package is not loadable from plain Node. `scriptdata.ts` reaches the
// canonical Japanese/Perso-Arabic/Tamil/Urdu inventories through a Vite virtual
// module (`virtual:script-ductus-inventories`), which only exists inside a Vite
// or Vitest process. Worse, the plugin that serves that virtual module imports
// `human-language-data` itself, so this package depends on the book generator.
// Making the book generator depend back on this package would close a cycle in
// the repository's build graph, and the build tool rejects cycles outright.
//
// So the two consumers meet in the middle, on DATA:
//
//     strokes.ts + the shipped font
//                |
//         ductusview.ts            <- the ONE renderer; nobody re-derives it
//                |
//        ┌───────┴────────┐
//        │                │
//   the live app     this ledger  ->  data/ductus/filmstrip-geometry.json
//   (SvgNode tree)                        |
//                                    the book's `script-filmstrip` figure
//
// Nothing here computes geometry. Every number and every path in the ledger is
// read back out of the `SvgNode` tree `ductusFilmstrip` produced, so a ledger
// that disagrees with the app is impossible by construction rather than by
// discipline — there is no second implementation to drift.
//
// Why the frames are stored as MARKUP and not as node trees
// ---------------------------------------------------------
// A frame is stored as an SVG fragment string, serialised here by `svgMarkup`.
// That is deliberate. `svgMarkup` is the audited boundary in this package: it
// escapes every attribute value and every text node, refuses tag/attribute
// names that are not legal XML names, and refuses anything beginning `on`.
// Storing trees instead would mean the book generator had to grow its own copy
// of that serialiser — a second escaping implementation, in the one place where
// a second implementation is most expensive to get wrong. Storing strings means
// the escaping happens exactly once, here, in the code that is tested for it.
//
// The consumer is still not asked to trust us: it re-checks each fragment
// against a conservative allowlist before it goes into a generated file.
// ---------------------------------------------------------------------------

import {
  ductusFilmstrip,
  svgMarkup,
  viewBoxFor,
  type DuctusOptions,
  type GlyphOutline,
  type SvgNode,
} from "./ductusview.ts";
import type { LetterDuctus, StrokeSource } from "./strokes.ts";

/** The box every frame of one letter shares, in SVG (post-flip) units. */
export interface FilmstripViewBox {
  minX: number;
  minY: number;
  width: number;
  height: number;
}

/** One frame: what it teaches, and the picture that teaches it. */
export interface FilmstripFrame {
  /** 1-based position across the whole letter. */
  number: number;
  /** The segment's own authored label — never re-worded here. */
  label: string;
  /** True when the hand must lift before this frame. */
  startsAfterLift: boolean;
  /**
   * The frame's picture as an SVG fragment, in the letter's shared viewBox
   * space. No `<svg>` wrapper: the consumer places it with its own transform.
   */
  markup: string;
}

/** Everything a second renderer needs to draw one letter's filmstrip. */
export interface FilmstripEntry {
  script: string;
  glyph: string;
  /** Editable lookup identity when `glyph` is a presentation-form outline. */
  sequence?: string;
  /** The font the outline was read from, relative to the curriculum root. */
  font: string;
  /** Where the stroke ORDER came from. Carried so the figure can print it. */
  source: StrokeSource;
  penLifts: number;
  /** "2 strokes · 1 pen lift · 5 movements". */
  summary: string;
  viewBox: FilmstripViewBox;
  frames: FilmstripFrame[];
}

/** The whole generated file. */
export interface FilmstripLedger {
  version: 1;
  generator: string;
  entries: FilmstripEntry[];
}

/** Where the generated ledger lives, relative to the curriculum root. */
export const FILMSTRIP_LEDGER_PATH = "data/ductus/filmstrip-geometry.json";

/** The line the generated file carries so nobody hand-edits it. */
export const FILMSTRIP_LEDGER_GENERATOR =
  "@coding-adventures/script-ductus — npm run generate:filmstrip-ledger";

/**
 * Frames are drawn side by side and nothing animates, so the printed strip
 * turns on `highlightSegment`: the part of the current stroke already travelled
 * drops back to the muted tone, and only the movement this frame's caption
 * names is in ink. Everything else is `ductusview`'s own default.
 */
export const FILMSTRIP_LEDGER_OPTIONS: DuctusOptions = { highlightSegment: true };

/** JSON keeps one decimal, matching the precision `penPathD` already rounds to. */
const round1 = (n: number): number => Math.round(n * 10) / 10;

/**
 * Roughly how many characters a caption line should hold.
 *
 * `ductusview` measures captions in FONT units, and font units are not
 * comparable between scripts: a Tamil box is about 1150 units wide and a
 * Perso-Arabic one about half that, so one fixed `captionSize` wraps a Tamil
 * caption at a comfortable two dozen characters and an Arabic caption at ten —
 * which stretches the panel until the words are taller than the letter. Fixing
 * the LINE LENGTH instead of the type size makes the panels comparable: every
 * script gets captions of about the same shape, in type scaled to its own box.
 *
 * 24 is what the hand-tuned default (`captionSize: 92`) already produced for
 * Tamil, so the scripts that looked right keep looking exactly as they did.
 */
const CAPTION_CHARACTERS_PER_LINE = 24;

/** `wrapCaption`'s own estimate of average character width, in ems. */
const AVERAGE_CHAR_WIDTH = 0.52;

/**
 * Caption type size for one letter, in that letter's font units.
 *
 * The width `viewBoxFor` reports does not depend on `captionSize` — only the
 * height does, through the caption band — so asking for the box first and
 * sizing the type from it is not circular.
 */
export function captionSizeFor(
  letter: LetterDuctus,
  outline: GlyphOutline,
  options: DuctusOptions,
): number {
  const { width } = viewBoxFor(letter, outline, options);
  return round1(width / (CAPTION_CHARACTERS_PER_LINE * AVERAGE_CHAR_WIDTH));
}

/**
 * Parse the `viewBox` attribute back into numbers.
 *
 * Reading it off the rendered frame rather than calling `viewBoxFor` again is
 * the point: if the two ever disagreed, this would be the file that noticed.
 * (We call `viewBoxFor` too, below, and require the answers to match.)
 */
function parseViewBox(attribute: unknown): FilmstripViewBox {
  const parts = String(attribute).trim().split(/\s+/).map(Number);
  if (parts.length !== 4 || parts.some((n) => !Number.isFinite(n))) {
    throw new Error(`filmstrip ledger: unreadable viewBox '${String(attribute)}'`);
  }
  return { minX: parts[0], minY: parts[1], width: parts[2], height: parts[3] };
}

/**
 * The frame's drawable children, serialised.
 *
 * `<title>` is dropped: it is the accessible name of a standalone `<svg>`, and
 * the strip gives the whole figure one title of its own. Everything else — the
 * flipped group holding the glyph, the strokes and the pen dot, and the caption
 * that must stay OUTSIDE that flip so it does not read backwards — is kept in
 * the order `ductusFrame` emitted it.
 */
function frameMarkup(frame: SvgNode): string {
  return (frame.children ?? [])
    .filter((child) => child.tag !== "title")
    .map(svgMarkup)
    .join("");
}

/**
 * One letter's ledger entry, read back out of the rendered filmstrip.
 *
 * `font` is recorded rather than derived so the entry states, on its own, which
 * outline it was built from. A ledger entry whose font moved is then a visible
 * change in the diff instead of a silent redraw.
 */
export function buildFilmstripEntry(
  letter: LetterDuctus,
  outline: GlyphOutline,
  font: string,
  options: DuctusOptions = FILMSTRIP_LEDGER_OPTIONS,
): FilmstripEntry {
  // Size the caption to this script's own box unless the caller has an opinion,
  // so a narrow Arabic panel is not two-thirds words. See `captionSizeFor`.
  const sized: DuctusOptions =
    options.captionSize === undefined
      ? { ...options, captionSize: captionSizeFor(letter, outline, options) }
      : options;
  const strip = ductusFilmstrip(letter, outline, sized);
  if (strip.frames.length === 0) {
    throw new Error(`${letter.script}:${letter.glyph} has no filmstrip frames`);
  }

  // Every frame of a letter shares one box; prove that here rather than trust
  // it, because the strip's layout arithmetic depends on it being true.
  const boxes = strip.frames.map((frame) => parseViewBox(frame.attrs.viewBox));
  const declared = viewBoxFor(letter, outline, sized);
  const expected = {
    minX: round1(declared.minX),
    minY: round1(declared.minY),
    width: round1(declared.width),
    height: round1(declared.height),
  };
  for (const box of boxes) {
    if (
      box.minX !== expected.minX ||
      box.minY !== expected.minY ||
      box.width !== expected.width ||
      box.height !== expected.height
    ) {
      throw new Error(
        `${letter.script}:${letter.glyph} frames disagree about their viewBox`,
      );
    }
  }

  return {
    script: letter.script,
    glyph: letter.glyph,
    ...(letter.sequence === undefined ? {} : { sequence: letter.sequence }),
    font,
    source: letter.source,
    penLifts: strip.penLifts,
    summary: strip.summary,
    viewBox: expected,
    frames: strip.steps.map((step, index) => ({
      number: step.number,
      label: step.label,
      startsAfterLift: step.startsAfterLift,
      markup: frameMarkup(strip.frames[index]),
    })),
  };
}

/**
 * The whole ledger, in one fixed order.
 *
 * Sorted by script then glyph by code point, so the file's byte order is a
 * property of its CONTENT and not of the order somebody happened to add the
 * targets in. That is what lets the check gate compare bytes.
 */
export function buildFilmstripLedger(entries: FilmstripEntry[]): FilmstripLedger {
  const seen = new Set<string>();
  for (const entry of entries) {
    const key = `${entry.script}:${entry.glyph}`;
    if (seen.has(key)) throw new Error(`filmstrip ledger: duplicate entry ${key}`);
    seen.add(key);
  }
  const sorted = [...entries].sort((left, right) => {
    if (left.script !== right.script) return left.script < right.script ? -1 : 1;
    return left.glyph < right.glyph ? -1 : left.glyph > right.glyph ? 1 : 0;
  });
  return {
    version: 1,
    generator: FILMSTRIP_LEDGER_GENERATOR,
    entries: sorted,
  };
}

/** The ledger's canonical bytes: two-space JSON, one trailing newline. */
export function serialiseFilmstripLedger(ledger: FilmstripLedger): string {
  return `${JSON.stringify(ledger, null, 2)}\n`;
}
